// Real HTTP, PostgreSQL triggers and Socket.IO against the disposable test database.
const assert=require('node:assert/strict'),path=require('node:path'),{createRequire}=require('node:module'),{randomUUID}=require('node:crypto'),{execFileSync}=require('node:child_process');
const root=path.resolve(__dirname,'../../..'),web=createRequire(root+'/apps/web/package.json'),{io}=web('socket.io-client');
let input='';process.stdin.on('data',chunk=>input+=chunk);process.stdin.on('end',()=>main(JSON.parse(input)).catch(error=>{console.error(error.message);process.exitCode=1}));
async function main(config){assert.equal(config.database,'otog_audit_test_20261021');assert.equal(config.base,'http://127.0.0.1:18021');const checks=[],sockets=[];
 const sql=query=>execFileSync('docker',['exec','-i','otog-postgres-1','psql','-X','-U','otog','-d',config.database,'-v','ON_ERROR_STOP=1','-tA'],{input:query,encoding:'utf8',stdio:['pipe','pipe','pipe']}).trim();
 async function request(route,token,method='GET',body,headers={}){const response=await fetch(config.base+route,{method,headers:{Authorization:'Bearer '+token,...headers},body});const text=await response.text();let value;try{value=JSON.parse(text)}catch{value=text}return{status:response.status,body:value}}
 async function upload(token,key,code='int main(){return 0;}'){const body=new FormData();body.set('language','cpp');body.set('sourceCode',new File([code],'fixture.cpp'));return request('/submission/problem/1',token,'POST',body,{'Idempotency-Key':key})}
 const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));async function until(test,label,timeout=6000){const end=Date.now()+timeout;while(Date.now()<end){if(test())return;await wait(30)}throw Error('Timed out: '+label)}
 async function connect(token){const socket=io(config.base,{auth:{token},transports:['websocket'],reconnection:false,timeout:3000});sockets.push(socket);const messages=[];socket.on('submission-progress',rows=>messages.push(...rows));await until(()=>socket.connected,'socket connection');return{socket,messages}}
 const watch=(socket,ids)=>new Promise((resolve,reject)=>socket.timeout(3000).emit('watch-submissions',{ids},(error,reply)=>error?reject(error):resolve(reply)));
 const finish=id=>sql(`BEGIN;INSERT INTO "submissionResult"("submissionId",result,score,"timeUsed","memUsed") VALUES(${id},'A',100,5,10);UPDATE submission SET status='accept',"updateDate"=clock_timestamp() WHERE id=${id};COMMIT;`);
 try{
  sql(`INSERT INTO "otogProblemKeywordRules"("problemId","requiredKeywords","bannedKeywords") VALUES(1,'{}','{}') ON CONFLICT("problemId") DO UPDATE SET "requiredKeywords"='{}',"bannedKeywords"='{}';UPDATE problem SET show=true WHERE id=1;`);
  const key=randomUUID(),responses=await Promise.all(Array.from({length:6},()=>upload(config.ownerToken,key)));assert(responses.every(x=>x.status===200));const sid=responses[0].body.id;assert(responses.every(x=>x.body.id===sid));assert.equal(sql(`SELECT count(*) FROM "otogSubmissionRequest" WHERE "requestId"='${key}'`),'1');
  assert.equal((await upload(config.ownerToken,key,'int main(){return 1;}')).status,409);assert.equal((await upload(config.ownerToken,'invalid')).status,400);
  sql('UPDATE problem SET show=false WHERE id=1');assert.equal((await upload(config.ownerToken,key)).body.id,sid);assert.equal((await upload(config.ownerToken,randomUUID())).status,400);sql('UPDATE problem SET show=true WHERE id=1');
  const other=await upload(config.otherToken,key);assert.equal(other.status,200);assert.notEqual(other.body.id,sid);checks.push('six concurrent retries create one job; replay survives changed eligibility, changed payload conflicts, invalid IDs fail, keys are scoped to the user');
  const hidden=Number(sql(`INSERT INTO submission("userId","problemId",status,language,"sourceCode","updateDate",public) VALUES(${config.otherId},2,'waiting','cpp','fixture',now(),true) RETURNING id` ).split('\n')[0]);
  const ids=[sid,other.body.id,hidden,2147483647];const batch=await request('/submission/progress?ids='+encodeURIComponent(JSON.stringify(ids)),config.ownerToken);assert.equal(batch.status,200);assert.deepEqual(batch.body.map(x=>x.id),[sid]);assert.equal((await request('/submission/'+other.body.id+'/progress',config.ownerToken)).status,403);assert.equal((await request('/submission/'+hidden+'/progress',config.ownerToken)).status,404);
  assert.equal((await request('/submission/progress?ids='+encodeURIComponent(JSON.stringify(Array(101).fill(sid))),config.ownerToken)).status,400);checks.push('batch and single progress preserve private/hidden permissions and reject oversized batches');
  const owner=await connect(config.ownerToken),admin=await connect(config.adminToken);assert.equal((await watch(owner.socket,ids)).live,true);await watch(admin.socket,ids);await until(()=>owner.messages.some(x=>x.id===sid),'initial snapshot');assert(owner.messages.every(x=>x.id===sid));await until(()=>admin.messages.some(x=>x.id===hidden),'admin hidden snapshot');
  sql(`UPDATE submission SET status='grading',"updateDate"=clock_timestamp() WHERE id=${sid}`);await until(()=>owner.messages.some(x=>x.id===sid&&x.status==='grading'),'database-triggered progress');finish(sid);await until(()=>owner.messages.some(x=>x.id===sid&&x.status==='accept'&&x.submissionResult?.score===100),'final result');
  assert.equal((await request('/submission/'+sid+'/rejudge',config.adminToken,'PATCH')).status,200);await until(()=>owner.messages.some(x=>x.id===sid&&x.status==='waiting'&&x.submissionResult===null),'rejudge clears old result');checks.push('real database notifications deliver progress/final results only to authorized watches, and rejudge clears the previous score');
  const unavailable=[];owner.socket.on('submission-live',ready=>unavailable.push(ready));sql(`SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname='${config.database}' AND application_name='otog-submission-events'`);await until(()=>unavailable.includes(false),'listener disconnect notification');finish(sid);await until(()=>unavailable.includes(true),'listener reconnect',10000);await until(()=>owner.messages.filter(x=>x.id===sid&&x.status==='accept').length>=2,'resync missed update',10000);
  owner.socket.disconnect();sql(`UPDATE submission SET status='grading',"updateDate"=clock_timestamp() WHERE id=${sid}`);const reconnected=await connect(config.ownerToken);await watch(reconnected.socket,[sid]);await until(()=>reconnected.messages.some(x=>x.status==='grading'),'client reconnect snapshot');checks.push('database-listener and client reconnects resynchronize changes missed while disconnected');
  const hiddenCount=admin.messages.filter(x=>x.id===hidden).length;sql(`UPDATE "user" SET role='user' WHERE id=${config.adminId};UPDATE submission SET status='grading',"updateDate"=clock_timestamp() WHERE id=${hidden}`);await wait(300);assert.equal(admin.messages.filter(x=>x.id===hidden).length,hiddenCount);
  sql(`UPDATE "refreshToken" SET used=true WHERE "userId"=${config.ownerId};UPDATE submission SET status='waiting',"updateDate"=clock_timestamp() WHERE id=${sid}`);await until(()=>!reconnected.socket.connected,'revoked watcher disconnect');checks.push('role demotion and session revocation are rechecked before publishing');
  console.log(JSON.stringify({passed:true,checks,productionWrites:0}));
 }finally{for(const socket of sockets)socket.disconnect()}
}
